#!/usr/bin/env python3
"""Project current v1 schemas and Desktop examples from the maintained decision examples."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
API = ROOT / 'decision-extensions/api'

def ref(name): return {'$ref': '#/components/schemas/' + name}
def obj(properties, required=None):
    return {'type': 'object', 'additionalProperties': False, 'required': list(properties) if required is None else required, 'properties': properties}
def array(items, minimum=0, maximum=None):
    return {'type': 'array', 'minItems': minimum, **({'maxItems': maximum} if maximum else {}), 'items': items}

def main():
    examples = json.loads((API / 'decision-examples.json').read_text())['cases']
    text = {'type': 'string', 'minLength': 1}
    identifier = {'type': 'string', 'minLength': 1, 'maxLength': 128}
    probability = {'type': 'number', 'minimum': 0, 'maximum': 1}
    groups = {'enum': [['regular'], ['regular', 'primary']]}
    schemas = {
        'Route': {'oneOf': [obj({'kind': {'const': 'smart_saving'}, 'groups': {'const': ['regular', 'primary']}}), obj({'kind': {'const': 'branches'}, 'categories': array(obj({'id': identifier, 'condition': text, 'groups': groups}), 2, 16), 'default_category': identifier})]},
        'ContentPart': {'oneOf': [obj({'kind': {'const': 'text'}, 'text': {'type': 'string'}}), obj({'kind': {'const': 'unavailable'}, 'source_kind': identifier})]},
        'StepPart': {'oneOf': [ref('ContentPart'), obj({'kind': {'const': 'tool_activity'}, 'tool': identifier, 'status': {'enum': ['completed', 'failed', 'unknown']}})]},
        'VisibleTurn': obj({'user': array(ref('ContentPart')), 'status': {'enum': ['completed', 'failed', 'interrupted', 'unknown']}, 'steps': array(array(ref('StepPart')))}),
        'PrecedingStage': obj({'from': {'type': 'integer', 'minimum': 0, 'description': 'Index in visible_conversation; the suffix is one actual preceding stage.'}, 'category': identifier, 'group': {'enum': ['regular', 'primary']}, 'complete': {'type': 'boolean'}}),
        'Assessment': obj({'score': probability, 'partial': {'type': 'boolean'}}),
        'ClassifierRequest': obj({'route': ref('Route'), 'latest_user': array(ref('ContentPart'), 1), 'visible_conversation': array(ref('VisibleTurn')), 'history_partial': {'type': 'boolean'}, 'preceding_stage': {'oneOf': [{'type': 'null'}, ref('PrecedingStage')]}}),
        'ClassifierResponse': obj({'category': identifier, 'group': {'enum': ['regular', 'primary']}, 'reason': {'type': 'string', 'minLength': 1, 'maxLength': 1024}, 'assessment': ref('Assessment')}, []),
    }
    content = lambda direction: {'schema': ref('ClassifierRequest' if direction == 'request' else 'ClassifierResponse'), 'examples': {case['name']: {'value': case[direction]} for case in examples if case['scope'] != 'future-docs-only'}}
    document = {'openapi': '3.1.0', 'info': {'title': 'HiRoute Decision API', 'version': '1.0.0', 'description': 'Current v1: extension-owned category/group decisions and optional observation-only assessment of a preceding actual stage.'}, 'servers': [{'url': 'https://classifier.example', 'description': 'Example only; HiRoute posts to the configured complete endpoint.'}], 'paths': {'/v1/decisions': {'post': {'operationId': 'decideAgentTurn', 'summary': 'Decide the current task and optionally assess a preceding stage', 'description': 'Every new user turn decides again. Tool continuations inherit only while same-turn history is continuous and the frozen decision remains reusable. Custom branches require a published category; a dual-group scope requires regular or primary. A single-group category ignores group. No model IDs, judgment prompts, rubric or routing thresholds cross this boundary. Missing/invalid group preserves a valid category and uses primary; invalid optional assessment is discarded independently, as is assessment when the new category differs from preceding_stage.category. Return strict JSON, no duplicate or unknown fields, at most 64 KiB.', 'requestBody': {'required': True, 'content': {'application/json': content('request')}}, 'responses': {'200': {'description': 'Decision with optional prior-stage assessment.', 'content': {'application/json': content('response')}}}}}}, 'components': {'schemas': schemas}}
    (API / 'decision.openapi.json').write_text(json.dumps(document, ensure_ascii=False, indent=2) + '\n')
    values = {name: {key: case[key] for key in ['request', 'response']} for name, case in [('first', next(case for case in examples if case['name'] == 'smart_saving')), ('assessment', next(case for case in examples if case['name'] == 'writing_review'))]}
    source = '// Generated by scripts/decision-contracts.py from the canonical v1 examples.\nexport const protocolExamples = ' + json.dumps(values, ensure_ascii=False, indent=2) + ';\n'
    source += '''export function protocolCurl(example: keyof typeof protocolExamples): string {
  return `curl --request POST 'https://classifier.example/v1/decisions' \\\\\\n  --header 'Content-Type: application/json' \\\\\\n  --data-raw '${JSON.stringify(protocolExamples[example].request, null, 2).replaceAll("'", "'\\\\''")}'`;
}
'''
    (ROOT / 'apps/desktop/src/features/decision-services/protocol-examples.ts').write_text(source)

if __name__ == '__main__': main()
